import{_ as o,c as t,o as a,ag as r}from"./chunks/framework.B3RpK1bM.js";const h=JSON.parse('{"title":"Low Code Development","description":"","frontmatter":{},"headers":[],"relativePath":"en_EN/low-code-development-instructions.md","filePath":"en_EN/low-code-development-instructions.md","lastUpdated":1769658044000}'),n={name:"en_EN/low-code-development-instructions.md"};function i(l,e,d,s,p,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="low-code-development" tabindex="-1">Low Code Development <a class="header-anchor" href="#low-code-development" aria-label="Permalink to &quot;Low Code Development&quot;">​</a></h1><p><a href="./">Return to Table of Contents</a></p><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><blockquote><p>Due to the Android program using apk tools for installation, it is generally possible to export an APK version; however, currently, it is not convenient for packaging and distribution. Therefore, this description states that current <strong>low-code development</strong> does not support the Android end.</p></blockquote><p>Ezgal supports Windows and Linux environments, while Mac users can manually create development templates by exporting from Godot.</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><p>Low-code development does not require configuration of the Godot or .NET development environment. The principle is to use open APIs to customize basic resources. To develop, you need to download the precompiled initial ezgal directory.</p><h3 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h3><p>You can directly obtain the corresponding release <a href="https://atomgit.com/godothub/ezgal/releases" target="_blank" rel="noreferrer">distribution</a>.</p><h3 id="use" tabindex="-1">Use <a class="header-anchor" href="#use" aria-label="Permalink to &quot;Use&quot;">​</a></h3><p>Open interfaces are managed in file folder form, and refer to the low-code development section in the framework structure diagram [to create corresponding folders] for reference. Scripting scripts for performances can be written according to the grammar design [section].</p><h3 id="low-code-development-editor" tabindex="-1">Low Code Development Editor <a class="header-anchor" href="#low-code-development-editor" aria-label="Permalink to &quot;Low Code Development Editor&quot;">​</a></h3><p>Ezgal defines a fixed interpretation language. For the interface of low-code development, they are all managed in text format. Future plans include developing an Ezgal editor to facilitate development settings and other workflows.</p><h3 id="case-studies" tabindex="-1">Case Studies <a class="header-anchor" href="#case-studies" aria-label="Permalink to &quot;Case Studies&quot;">​</a></h3><p>Below are some game development cases based on Ezgal:</p><ul><li><a href="https://atomgit.com/cryingn/The_Guilty_Secret" target="_blank" rel="noreferrer">The Guilty Secret</a></li></ul><h2 id="distribution" tabindex="-1">Distribution <a class="header-anchor" href="#distribution" aria-label="Permalink to &quot;Distribution&quot;">​</a></h2><p>When distributing projects, you should package the initial ezgal program along with related files within the resource directory.</p>',18)])])}const m=o(n,[["render",i]]);export{h as __pageData,m as default};
